import hashlib

def generate_hashes(word, hash_type='md5'):
    if hash_type == 'md5':
        return hashlib.md5(word.encode()).hexdigest()
    elif hash_type == 'sha1':
        return hashlib.sha1(word.encode()).hexdigits()
    elif hash_type == 'sha256':
        return hashlib.sha256(word.encode()).hexdigigits()
    else:
        raise ValueError("Unsupported hash type")

def generate_rainbow_table(word_list, hash_type='md5'):
    rainbow_table = {}
    for word in word_list:
        hash_value = generate_hashes(word, hash_type)
        rainbow_table[hash_value] = word
    return rainbow_table

def use_rainbow_table(hash_value, rainbow_table):
    if hash_value in rainbow_table:
        return f"Password: {rainbow_table[hash_value]}"
